// ═══════════════════════════════════════════════════════════════════════
// FILE: Licensing/Contracts/LicensePlanCatalog.cs
// PROJECT: ProGlass.Licensing
// MODULE: Global license-plan service (single source of truth)
//
// ONE place defines the five sellable plans. BOTH sides use it:
//   • the License Generator (vendor tool) — plan picker + signing,
//   • the customer app — plan cards, GET LICENSE KEY request text and
//     the paste-time plan-mismatch guard (wrong-plan warnings).
// A plan key generated by the vendor tool and pasted in the app is
// therefore compared against the SAME catalog on both ends.
// ═══════════════════════════════════════════════════════════════════════

using System;
using System.Collections.Generic;
using System.Linq;

namespace ProGlass.Licensing;

public static class LicensePlanCatalog
{
    /// <summary>A sellable validity window.</summary>
    public sealed record Plan(string Name, int Days);

    /// <summary>The five sellable plans, in UI order.</summary>
    public static IReadOnlyList<Plan> All { get; } = new[]
    {
        new Plan("7 Days", 7),
        new Plan("30 Days", 30),
        new Plan("6 Months", 182),
        new Plan("1 Year", 365),
        new Plan("2 Years", 730)
    };

    /// <summary>Closest sellable plan for an arbitrary day count.</summary>
    public static Plan FromDays(int days)
    {
        int clamped = Math.Max(1, days);
        return All.OrderBy(p => Math.Abs(p.Days - clamped)).First();
    }

    /// <summary>Human duration label ("7 days", "6 months", "1 year"…).</summary>
    public static string DurationLabel(int days) => days switch
    {
        7 => "7 days",
        30 => "30 days",
        182 => "6 months",
        365 => "1 year",
        730 => "2 years",
        _ => days + " days"
    };

    /// <summary>
    /// Map an issued/expires window to the closest sellable plan.
    /// Returns null for open-ended (no expiry) or non-plan windows —
    /// callers treat null as "no plan logic applies".
    /// </summary>
    public static Plan? FromValidityWindow(DateTime issuedUtc, DateTime? expiresUtc)
    {
        if (expiresUtc == null) return null;
        double days = (expiresUtc.Value - issuedUtc).TotalDays;
        if (days <= 0 || days > 800) return null;   // >800d ≈ open-ended
        return FromDays((int)Math.Round(days));
    }

    /// <summary>Plan of a signed license document (null = open-ended).</summary>
    public static Plan? Of(LicenseDocument? doc)
    {
        if (doc?.ExpiresAtUtc == null) return null;
        return FromValidityWindow(doc.IssuedAtUtc, doc.ExpiresAtUtc);
    }
}
